<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { RouterLink } from 'vue-router'
import { generatedCourseApi, profileApi } from '@/api'
import { useProgressStore } from '@/stores/progress'

const progress=useProgressStore(), now=new Date(), month=ref(new Date(now.getFullYear(),now.getMonth(),1))
const profile=reactive({username:'',nickname:'',email:'',avatar:''}), courses=ref<any[]>([]), activities=ref<any[]>([]), achievements=ref<any[]>([]), saving=ref(false), message=ref(''), error=ref('')
const monthLabel=computed(()=>`${month.value.getFullYear()}年${month.value.getMonth()+1}月`)
const days=computed(()=>{const first=new Date(month.value.getFullYear(),month.value.getMonth(),1),total=new Date(month.value.getFullYear(),month.value.getMonth()+1,0).getDate();return [...Array(first.getDay()).fill(null),...Array.from({length:total},(_,i)=>i+1)]})
const activityMap=computed(()=>new Map(activities.value.map((a:any)=>[a.date,a])))
function key(day:number){return `${month.value.getFullYear()}-${String(month.value.getMonth()+1).padStart(2,'0')}-${String(day).padStart(2,'0')}`}
function dayInfo(day:number){return activityMap.value.get(key(day)) as any}
function intensity(day:number){const s=dayInfo(day)?.seconds||0;return s>=3600?'level-4':s>=1800?'level-3':s>=600?'level-2':s>0?'level-1':''}
async function loadMonth(){activities.value=await profileApi.calendar(month.value.getFullYear(),month.value.getMonth()+1)}
async function changeMonth(step:number){month.value=new Date(month.value.getFullYear(),month.value.getMonth()+step,1);await loadMonth()}
async function saveProfile(){saving.value=true;message.value='';error.value='';try{Object.assign(profile,await profileApi.update(profile));message.value='个人资料已保存'}catch(e:any){error.value=e?.message||'保存失败'}finally{saving.value=false}}
onMounted(async()=>{await Promise.all([progress.load().catch(()=>{}),profileApi.get().then(v=>Object.assign(profile,v)).catch(()=>{}),generatedCourseApi.list().then(v=>courses.value=v).catch(()=>{}),loadMonth().catch(()=>{}),profileApi.achievements().then(v=>achievements.value=v).catch(()=>{})])})
</script>

<template>
 <div class="container center-page"><header class="center-head"><div><p class="eyebrow">个人学习中心</p><h1>继续你的学习</h1></div><RouterLink class="btn btn--primary" to="/ai/courses">＋ 从资料生成课程</RouterLink></header>
  <section class="stats"><article class="card stat"><strong>{{progress.summary.completed}}</strong><span>已完成课时</span></article><article class="card stat"><strong>{{Math.floor(progress.summary.totalSeconds/3600)}}h {{Math.floor(progress.summary.totalSeconds%3600/60)}}m</strong><span>真实学习时长</span></article><article class="card stat"><strong>{{progress.summary.studyCount}}</strong><span>学习次数</span></article><article class="card stat"><strong>{{courses.length}}</strong><span>我的导入课程</span></article></section>
  <div class="center-grid"><section class="card panel"><div class="section-head"><div><h2>我的学习</h2><p>继续上次学习的课时，进度来自实际阅读记录。</p></div><RouterLink to="/course/java-mastery">课程目录</RouterLink></div>
    <div v-if="progress.items.length" class="continue-list"><RouterLink v-for="item in progress.items.slice(0,6)" :key="item.lessonId" class="continue-item" :to="`/lesson/${item.slug}`"><div><strong>{{item.title}}</strong><small>{{item.moduleTitle}} · {{item.progressPct}}% · {{Math.floor(item.totalSeconds/60)}} 分钟</small></div><span>继续 →</span></RouterLink></div><p v-else class="empty">还没有学习记录，打开一节课开始学习吧。</p>
    <h3>我的收藏</h3><RouterLink v-for="f in progress.favorites.slice(0,5)" :key="f.lessonId" class="favorite" :to="`/lesson/${f.slug}`">★ {{f.title}}</RouterLink><p v-if="!progress.favorites.length" class="empty">收藏的课时会显示在这里。</p>
  </section>
  <section class="card panel calendar"><div class="section-head"><div><h2>学习日历</h2><p>仅记录实际计时和完成课时。</p></div><div class="month-nav"><button @click="changeMonth(-1)">‹</button><b>{{monthLabel}}</b><button @click="changeMonth(1)">›</button></div></div><div class="calendar-grid"><span v-for="d in ['日','一','二','三','四','五','六']" :key="d" class="weekday">{{d}}</span><template v-for="(d,i) in days" :key="i"><span v-if="!d" class="day blank"></span><span v-else class="day" :class="intensity(d)" :title="`${key(d)} · ${Math.floor((dayInfo(d)?.seconds||0)/60)}分钟 · 完成${dayInfo(d)?.completed||0}课时`">{{d}}</span></template></div><div class="legend"><span>少</span><i class="level-1"></i><i class="level-2"></i><i class="level-3"></i><i class="level-4"></i><span>多</span></div>
    <h3>可验证成就</h3><div class="achievement-list"><div v-for="a in achievements" :key="a.id" class="achievement" :class="{'unlocked':a.unlocked}"><b>{{a.unlocked?'🏅':'🔒'}} {{a.title}}</b><small>{{a.description}}</small></div></div>
  </section></div>
  <section class="card panel my-courses"><div class="section-head"><div><h2>我的课程</h2><p>你创建的课程默认为私有，可管理只读分享链接。</p></div><RouterLink to="/ai/courses">课程工作台 →</RouterLink></div><div v-if="courses.length" class="course-list"><article v-for="c in courses" :key="c.id" class="course-row"><div><b>{{c.title}}</b><small>{{c.sourceName||c.sourceUrl}} · {{c.status==='DRAFT'?'草稿':'已发布'}}</small></div><RouterLink class="btn btn--sm btn--ghost" :to="{path:'/ai/courses',query:{id:c.id}}">{{c.status==='DRAFT'?'编辑':'查看'}}</RouterLink></article></div><p v-else class="empty">还没有导入课程，试试上传一份学习资料。</p></section>
  <section class="card panel profile-panel"><div class="section-head"><div><h2>个人资料</h2><p>账号邮箱和头像不会公开展示。</p></div></div><div class="profile-form"><label>用户名<input v-model="profile.username" disabled /></label><label>昵称<input v-model="profile.nickname" maxlength="64" /></label><label>邮箱<input v-model="profile.email" type="email" maxlength="128" /></label><label>头像链接<input v-model="profile.avatar" maxlength="255" placeholder="可选的图片链接" /></label><button class="btn btn--primary" :disabled="saving" @click="saveProfile">{{saving?'保存中…':'保存资料'}}</button><span v-if="message" class="success">{{message}}</span><span v-if="error" class="error">{{error}}</span></div></section>
 </div>
</template>

<style scoped>
.center-page{padding:28px 0 50px}.center-head,.section-head{display:flex;align-items:center;justify-content:space-between;gap:16px}.center-head{margin-bottom:22px}.eyebrow{margin:0;color:var(--c-mint);font-weight:800}.center-head h1{margin:4px 0}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin-bottom:20px}.stat{padding:18px 20px;display:flex;flex-direction:column;gap:4px}.stat strong{font-size:26px;color:var(--c-ink)}.stat span,.section-head p,.empty{font-size:13px;color:var(--c-ink-faint)}.center-grid{display:grid;grid-template-columns:1fr 1fr;gap:20px}.panel{padding:22px;margin-bottom:20px}.section-head h2{margin:0 0 4px}.section-head p{margin:0}.continue-item,.course-row{display:flex;justify-content:space-between;align-items:center;gap:12px;padding:12px 0;border-bottom:1px solid var(--c-cream-deep);color:inherit;text-decoration:none}.continue-item:hover,.favorite:hover{color:var(--c-coral)}.continue-item div,.course-row div{display:flex;flex-direction:column;gap:4px}.continue-item small,.course-row small,.achievement small{color:var(--c-ink-faint);font-size:12px}.panel h3{margin:20px 0 10px}.favorite{display:inline-block;margin:0 12px 6px 0;color:var(--c-ink-soft);text-decoration:none}.month-nav{display:flex;gap:10px;align-items:center}.month-nav button{border:0;background:var(--c-cream-deep);border-radius:8px;width:30px;height:30px;font-size:20px;cursor:pointer}.calendar-grid{display:grid;grid-template-columns:repeat(7,1fr);gap:6px;margin-top:18px}.weekday,.day{display:grid;place-items:center;aspect-ratio:1;border-radius:9px;font-size:12px}.weekday{font-weight:700;color:var(--c-ink-faint)}.day{background:var(--c-cream-deep)}.day.level-1,.legend .level-1{background:#b4e2d5}.day.level-2,.legend .level-2{background:#73c9af}.day.level-3,.legend .level-3{background:#36a98b;color:#fff}.day.level-4,.legend .level-4{background:#187b65;color:#fff}.legend{display:flex;align-items:center;justify-content:flex-end;gap:5px;margin-top:9px;color:var(--c-ink-faint);font-size:11px}.legend i{width:13px;height:13px;border-radius:4px}.achievement-list{display:grid;grid-template-columns:1fr 1fr;gap:8px}.achievement{display:flex;flex-direction:column;gap:3px;padding:10px;border-radius:10px;background:var(--c-cream);opacity:.66}.achievement.unlocked{opacity:1;background:#edf8f3}.profile-form{display:grid;grid-template-columns:1fr 1fr;gap:12px}.profile-form label{display:flex;flex-direction:column;gap:5px;font-weight:700}.profile-form input{padding:10px;border:2px solid var(--c-line);border-radius:10px;background:var(--c-paper);color:var(--c-ink)}.profile-form button{width:max-content}.success{color:#21815d}.error{color:var(--c-coral-deep)}@media(max-width:760px){.stats{grid-template-columns:1fr 1fr}.center-grid{grid-template-columns:1fr}.center-head,.section-head{align-items:flex-start;flex-direction:column}.profile-form{grid-template-columns:1fr}}
</style>
